package net.thunderbird.android.evaarta

class EvaartaWiFiTransport(private val sender:suspend (EvaartaEnvelope)->Result<Unit>,private val available:()->Boolean):EvaartaTransport{override val id="wifi-lan";override fun isAvailable()=available();override suspend fun send(envelope:EvaartaEnvelope)=if(isAvailable())sender(envelope) else Result.failure(IllegalStateException("Wi-Fi unavailable"))}
